  // Phase 1 — live Ollama scoring (qwen2-vl vision if image fetchable, qwen3:14b text fallback)
  async scoreThumbnails(mediaItems: MediaItem[]): Promise<ScoredMediaItem[]> {
    const OLLAMA_BASE = process.env.OLLAMA_HOST || 'http://localhost:11434';
    const results: ScoredMediaItem[] = [];
    for (const item of mediaItems) {
      try {
        let imageBase64: string | null = null;
        let model = 'qwen3:14b';
        try {
          const imgRes = await fetch(item.url);
          if (imgRes.ok) {
            const buf = await imgRes.arrayBuffer();
            imageBase64 = Buffer.from(buf).toString('base64');
            model = 'qwen2-vl';
          }
        } catch { /* image fetch failed — text fallback */ }
        const prompt = imageBase64
          ? 'Rate this image for TikTok visual appeal (0-100). Respond ONLY with JSON: {"score":<number>,"tags":["..."],"reason":"..."}'
          : `Rate the TikTok visual appeal of an archive media item at ${item.url} (0-100). Respond ONLY with JSON: {"score":<number>,"tags":[],"reason":"..."}`;
        const reqBody: Record<string, unknown> = { model, prompt, stream: false, options: { num_predict: 128, temperature: 0.1 } };
        if (imageBase64) reqBody.images = [imageBase64];
        const res = await fetch(`${OLLAMA_BASE}/api/generate`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(reqBody),
        });
        if (!res.ok) throw new Error(`Ollama returned ${res.status}`);
        const ollamaJson = await res.json() as { response: string };
        const jsonMatch = ollamaJson.response.match(/\{[\s\S]*\}/);
        const parsed = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
        const score = typeof parsed.score === 'number' ? Math.min(100, Math.max(0, parsed.score)) : 50;
        results.push({ ...item, confidence: config.confidenceThreshold, score, status: 'success' as const });
      } catch (error) {
        console.error(`Scoring failed for ${item.url}:`, (error as Error).message);
        results.push({ ...item, confidence: 0, score: 0, status: 'error' as const });
      }
    }
    return results;
  }
